class StockPrice {
    private java.util.HashMap<Integer, Integer> tsPrice;
    private java.util.TreeMap<Integer, Integer> priceCount;
    private int latestTs;

    public StockPrice() {
        tsPrice = new java.util.HashMap<>();
        priceCount = new java.util.TreeMap<>();
        latestTs = 0;
    }

    public void update(int timestamp, int price) {
        if (tsPrice.containsKey(timestamp)) {
            int oldPrice = tsPrice.get(timestamp);
            int cnt = priceCount.get(oldPrice);
            if (cnt == 1) priceCount.remove(oldPrice);
            else priceCount.put(oldPrice, cnt - 1);
        }
        tsPrice.put(timestamp, price);
        priceCount.merge(price, 1, Integer::sum);
        latestTs = Math.max(latestTs, timestamp);
    }

    public int current() {
        return tsPrice.get(latestTs);
    }

    public int maximum() {
        return priceCount.lastKey();
    }

    public int minimum() {
        return priceCount.firstKey();
    }
}

import java.util.*;

class StockPrice {
    private Map<Integer, Integer> tsPrice;
    private PriorityQueue<int[]> maxHeap;
    private PriorityQueue<int[]> minHeap;
    private int latestTs;

    public StockPrice() {
        tsPrice = new HashMap();
        maxHeap = new PriorityQueue(new Comparator<int[]>() {
            public int compare(int[] a, int[] b) { return b[0] - a[0]; }
        });
        minHeap = new PriorityQueue(new Comparator<int[]>() {
            public int compare(int[] a, int[] b) { return a[0] - b[0]; }
        });
        latestTs = 0;
    }

    public void update(int timestamp, int price) {
        tsPrice.put(timestamp, price);
        maxHeap.offer(new int[]{price, timestamp});
        minHeap.offer(new int[]{price, timestamp});
        latestTs = Math.max(latestTs, timestamp);
    }

    public int current() {
        return tsPrice.get(latestTs).intValue();
    }

    public int maximum() {
        while (true) {
            int[] top = maxHeap.peek();
            if (tsPrice.get(top[1]).intValue() == top[0]) return top[0];
            maxHeap.poll();
        }
    }

    public int minimum() {
        while (true) {
            int[] top = minHeap.peek();
            if (tsPrice.get(top[1]).intValue() == top[0]) return top[0];
            minHeap.poll();
        }
    }
}
